from lib89 import *
def B(ch,tn,*a,**k): build('science',ch,tn,*a,**k)
B(7,'Work, energy and simple machines','Work, energy, power and simple machines','Lifting a bucket from the well',
 "Lifting a bucket from a well, pushing a cart, pedalling a cycle: each needs work and uses energy. Simple machines like levers and pulleys make this work easier.",
 [("Work is done when a force moves an object in the direction of the force: W = F x s. The SI unit is the joule.","W = F s"),
  ("The work-energy theorem says the net work done on an object equals the change in its kinetic energy.","work-energy theorem"),
  ("Energy is the capacity to do work. It exists in forms such as kinetic, potential, heat, light, sound, electrical and chemical energy.","forms of energy"),
  ("Kinetic energy is 1/2 m v^2 and gravitational potential energy is m g h. Their sum is the mechanical energy.","KE = 1/2 mv^2, PE = mgh"),
  ("Energy changes from one form to another but the total remains the same. This is the law of conservation of energy.","conservation of energy"),
  ("Power is the rate of doing work: P = W/t. Its SI unit is the watt, 1 W = 1 J/s.","P = W/t"),
  ("Simple machines like the lever, pulley and inclined plane let us lift a load with a smaller effort.","simple machines"),
  ("Mechanical advantage is the load divided by the effort. A machine that gives MA greater than 1 makes the task easier.","MA = load/effort")],
 ("A 2 kg stone is lifted 5 m. Find the potential energy gained (g = 10 m/s^2).",[("PE = m g h.","Use the formula."),("= 2 x 10 x 5.","Substitute."),("= 100 J.","Joule is the unit.")]),
 ("Define work, energy and power with units.",["W = Fs in joule","Energy as capacity for work","P = W/t in watt"],["Thinking work is done when you push a wall that does not move"]),
 ["Work = force x displacement (joule).","KE = 1/2 mv^2 and PE = mgh.","Energy is conserved.","Power = work/time (watt); machines have mechanical advantage."],
 [mcq("s7-1",1,"The SI unit of work is the","joule",["watt","newton"],"Joule = newton metre."),
  mcq("s7-2",1,"Power is the rate of","doing work",["change in mass","increase in force"],"P = W/t."),
  tf("s7-3",1,"Energy can be created from nothing.",False,"Energy is conserved."),
  num("s7-4",2,"KE (J) of a 2 kg body moving at 3 m/s",9,"1/2 x 2 x 9.",[(18,"Remember the 1/2.")]),
  num("s7-5",2,"Work (J) when 10 N moves a body 3 m along the force",30,"10 x 3.",[(13,"Multiply, not add.")]),
  num("s7-6",2,"Power (W) if 600 J of work is done in 20 s",30,"600/20.",[(12000,"Divide work by time.")]),
  short("s7-7",3,"What is the SI unit of power? (one word)",["watt"],"Watt."),
  mcq("s7-8",3,"A lever with load 100 N and effort 20 N has MA","5",["80","0.2"],"100/20.")])
B(8,'Structure of the atom','Journey inside the atom: models, atomic number, mass number and valency','Smaller than small',
 "Break a piece of chalk, again and again. Is there a smallest piece? Ancient Indian and Greek thinkers wondered about this, and modern science found that atoms themselves have parts.",
 [("The idea of atoms goes back to ancient thinkers in India and Greece, and was developed scientifically by Dalton.","roots of atomic theory"),
  ("Thomson found the electron and proposed a model with electrons in a positive sphere. Rutherford's gold foil experiment showed a tiny dense nucleus.","Thomson and Rutherford"),
  ("Bohr's model puts electrons in fixed orbits or energy levels around the nucleus.","Bohr model"),
  ("An atom has protons (positive) and neutrons (no charge) in the nucleus and electrons (negative) around it.","protons, neutrons, electrons"),
  ("The atomic number Z is the number of protons. It identifies the element.","atomic number"),
  ("The mass number A is protons plus neutrons.","mass number"),
  ("Electrons fill energy levels in order: at most 2 in the first shell and 8 in the second.","electron distribution"),
  ("Valency is the combining capacity of an atom and depends on the electrons in the outermost shell.","valency")],
 ("Find protons, neutrons and electrons in sodium with Z = 11 and A = 23. Give its electron arrangement.",[("Protons = 11 and electrons = 11.","Neutral atom."),("Neutrons = 23 - 11 = 12.","A minus Z."),("Arrangement 2, 8, 1, so valency 1.","Fill shells.")]),
 ("Describe the Rutherford model and define atomic and mass number.",["Dense positive nucleus","Z = protons","A = protons + neutrons"],["Thinking electrons are in the nucleus"]),
 ["Atoms contain protons, neutrons and electrons.","Rutherford discovered the nucleus; Bohr gave energy levels.","Atomic number = protons; mass number = protons + neutrons.","Valency depends on outer electrons."],
 [mcq("s8-1",1,"The atomic number is the number of","protons",["neutrons","electrons plus neutrons"],"Z is the proton count."),
  mcq("s8-2",1,"Rutherford discovered the","nucleus",["electron","neutron"],"Gold foil experiment."),
  tf("s8-3",1,"Neutrons carry a negative charge.",False,"Neutrons are neutral."),
  num("s8-4",2,"Neutrons in an atom with A = 23 and Z = 11",12,"23 - 11.",[(34,"Subtract; do not add.")]),
  num("s8-5",2,"Maximum electrons in the second shell",8,"The second shell holds 8.",[(2,"2 is the first shell.")]),
  mcq("s8-6",2,"Sodium (2, 8, 1) has valency","1",["2","8"],"It has 1 outer electron."),
  short("s8-7",3,"Which particle has a negative charge? (one word)",["electron"],"Electrons."),
  tf("s8-8",3,"Mass number is protons plus neutrons.",True,"A = p + n.")])
B(10,'Sound waves','Sound: propagation, waves, characteristics and reflection','The drum and the echo',
 "Hit a drum and you hear it across the room. Shout towards a hill and your voice returns. Sound travels as a wave, and a few characteristics describe it completely.",
 [("Sound is produced by vibrating objects and needs a medium such as air, water or a solid to travel. It cannot travel through a vacuum.","medium needed"),
  ("Sound travels as a longitudinal wave of compressions and rarefactions.","compressions and rarefactions"),
  ("Sound waves carry energy. The speed of sound in air is about 346 m/s at 25 degrees Celsius.","speed of sound"),
  ("The distance between two successive compressions is the wavelength; the number of vibrations per second is the frequency, in hertz.","wavelength and frequency"),
  ("Speed, frequency and wavelength are related: v = f x wavelength.","v = f lambda"),
  ("Amplitude is the maximum displacement; it decides loudness. Frequency decides pitch.","loudness and pitch"),
  ("Sound is reflected by hard surfaces, which gives echoes. Reflection also follows the laws of reflection.","reflection and echo"),
  ("Curved ceilings and walls in halls reflect sound so that it reaches the audience better.","use of reflection")],
 ("A wave has frequency 500 Hz and wavelength 0.7 m. Find its speed.",[("v = f x wavelength.","Wave relation."),("= 500 x 0.7.","Substitute."),("= 350 m/s.","Speed of sound.")]),
 ("What decides pitch and what decides loudness?",["Frequency decides pitch","Amplitude decides loudness","Sound needs a medium"],["Saying sound travels in vacuum"]),
 ["Sound is a longitudinal wave needing a medium.","v = f x wavelength.","Pitch depends on frequency, loudness on amplitude.","Reflection of sound produces echoes."],
 [mcq("s10-1",1,"Sound cannot travel through","a vacuum",["water","steel"],"It needs a medium."),
  mcq("s10-2",1,"Pitch depends on","frequency",["amplitude","speed only"],"Higher frequency, higher pitch."),
  tf("s10-3",1,"Sound is a transverse wave.",False,"It is longitudinal."),
  num("s10-4",2,"Speed (m/s) of a wave with f = 500 Hz and wavelength 0.7 m",350,"500 x 0.7.",[(700,"Do not double.")]),
  mcq("s10-5",2,"Loudness depends on","amplitude",["frequency","wavelength"],"Larger amplitude, louder sound."),
  tf("s10-6",2,"An echo is due to reflection of sound.",True,"Sound bounces back."),
  short("s10-7",3,"The unit of frequency is the",["hertz","hz"],"Hertz."),
  mcq("s10-8",3,"Compression regions in a sound wave have","higher pressure",["lower pressure","no air"],"Particles are crowded.")])
B(11,'Reproduction','Reproduction in plants, animals and humans','Life goes on',
 "A potato sprouts from an eye, a hen lays eggs and a mother gives birth. Different methods, one purpose: life continues.",
 [("Reproduction is the process by which organisms produce new individuals of their own kind.","reproduction"),
  ("Asexual reproduction involves one parent and gives offspring identical to it. Examples are binary fission, budding, fragmentation and vegetative propagation.","asexual reproduction"),
  ("Sexual reproduction involves two parents and the fusion of gametes, so offspring show variation.","sexual reproduction"),
  ("In flowers, pollination is the transfer of pollen from anther to stigma. It can be self or cross pollination, by wind, water, insects or animals.","pollination"),
  ("After fertilisation the ovule becomes a seed and the ovary becomes a fruit.","seed and fruit"),
  ("In animals sexual reproduction involves fertilisation, which may be external, as in frogs, or internal, as in humans.","fertilisation"),
  ("In humans the male gamete is the sperm and the female gamete is the egg. The fertilised egg is a zygote that develops in the uterus.","human reproduction"),
  ("Sexual reproduction increases variation, which helps species survive changes in the environment.","variation")],
 ("Why do children of the same parents look different from each other?",[("Each child receives a different mix of genes from the two parents.","Gametes carry half the genes."),("Fertilisation combines sperm and egg randomly.","Different combinations."),("So sexual reproduction gives variation.","Unlike cloning.")]),
 ("Compare asexual and sexual reproduction.",["One parent and identical offspring","Two parents and variation","Examples of each"],["Thinking pollination and fertilisation are the same"]),
 ["Asexual reproduction needs one parent; sexual needs two.","Pollination is the transfer of pollen; fertilisation is the fusion of gametes.","The zygote develops into an embryo.","Sexual reproduction produces variation."],
 [mcq("s11-1",1,"Budding in Hydra is","asexual reproduction",["sexual reproduction","pollination"],"One parent."),
  mcq("s11-2",1,"Transfer of pollen from anther to stigma is","pollination",["fertilisation","germination"],"By definition."),
  tf("s11-3",1,"Sexual reproduction needs two gametes.",True,"Sperm and egg or pollen and ovule."),
  mcq("s11-4",2,"After fertilisation the ovary develops into a","fruit",["seed","flower"],"The ovary becomes the fruit."),
  mcq("s11-5",2,"The fertilised egg is called a","zygote",["gamete","embryo sac"],"Zygote."),
  tf("s11-6",2,"Offspring of asexual reproduction show large variation.",False,"They are identical."),
  short("s11-7",3,"Which type of fertilisation occurs in frogs: external or internal?",["external"],"Frogs fertilise outside the body."),
  mcq("s11-8",3,"Variation helps species","survive changes in the environment",["stay identical","stop reproducing"],"Variation increases survival chances.")])
B(12,'Diversity and classification','Biodiversity and the five kingdom classification','Sorting living things',
 "A forest has trees, birds, insects, fungi and bacteria. To study millions of organisms, scientists sort them into groups by common features.",
 [("India is a biodiversity hotspot, a region with a very large variety of species.","biodiversity hotspot"),
  ("We classify organisms because a system of groups makes it easy to study, name and compare them.","need for classification"),
  ("Classification uses features such as cell type, body organisation and mode of nutrition.","criteria"),
  ("The five kingdoms are Monera, Protista, Fungi, Plantae and Animalia.","five kingdoms"),
  ("Monera are prokaryotes like bacteria. Protista are unicellular eukaryotes like Amoeba.","Monera and Protista"),
  ("Fungi are eukaryotes that absorb nutrients and have cell walls; Plantae make food by photosynthesis; Animalia are multicellular consumers without cell walls.","other kingdoms"),
  ("Fossils are preserved remains of ancient organisms and are evidence of how life has changed over time.","fossils"),
  ("Some entities, like viruses, are acellular and do not fit neatly into the five kingdoms.","acellular entities")],
 ("Place a multicellular organism without chlorophyll that absorbs nutrients from a host.",[("It is eukaryotic and multicellular.","Has nuclei."),("No chlorophyll and absorbs nutrients externally.","Not a plant."),("This fits Fungi.","Heterotrophic absorption.")]),
 ("Name the five kingdoms and one feature of each.",["Monera prokaryote","Fungi absorb food","Plantae photosynthesise"],["Calling viruses a kingdom member"]),
 ["Classification organises diversity.","There are five kingdoms.","Fossils are evidence of past life.","Viruses are acellular and are a special case."],
 [mcq("s12-1",1,"Bacteria belong to kingdom","Monera",["Fungi","Animalia"],"They are prokaryotes."),
  mcq("s12-2",1,"Which kingdom makes food by photosynthesis?","Plantae",["Fungi","Monera"],"Plants have chlorophyll."),
  tf("s12-3",1,"Fossils are evidence of past life.",True,"They preserve ancient organisms."),
  mcq("s12-4",2,"Amoeba is a","unicellular eukaryote",["prokaryote","multicellular plant"],"Protista."),
  mcq("s12-5",2,"Fungi get food by","absorbing nutrients",["photosynthesis","hunting"],"Heterotrophs."),
  tf("s12-6",2,"There are five kingdoms in this classification.",True,"Monera, Protista, Fungi, Plantae, Animalia."),
  short("s12-7",3,"Name the kingdom of multicellular consumers without cell walls.",["animalia"],"Animalia."),
  mcq("s12-8",3,"Why do we classify organisms?","To study and compare them easily",["To create more species","To destroy diversity"],"Order makes study easy.")])
B(13,'Earth as a system','Earth as a system: heating, winds, currents and biogeochemical cycles','The restless planet',
 "The Sun heats the Earth, but not evenly. That single fact drives the winds, ocean currents and the cycles of water, carbon, nitrogen and oxygen that keep life going.",
 [("The Sun's energy reaches the Earth as radiation, but different places receive different amounts because of latitude and the Earth's shape.","uneven heating"),
  ("Regions near the equator receive sunlight more directly and are warmer; polar regions receive slanting rays and are colder.","latitude"),
  ("The atmosphere acts like a blanket. Greenhouse gases trap heat, which keeps the Earth warm enough for life.","greenhouse effect"),
  ("Uneven heating causes winds. Local winds like sea and land breezes, and planetary winds, blow from higher to lower pressure.","winds"),
  ("Ocean currents also move heat around the Earth.","ocean currents"),
  ("Biogeochemical cycles move matter between living and non-living parts: the water, carbon, nitrogen and oxygen cycles.","biogeochemical cycles"),
  ("In the water cycle, water evaporates, condenses into clouds and returns as precipitation. In the carbon cycle, plants fix carbon dioxide and respiration and burning release it.","water and carbon cycles"),
  ("Human activities such as burning fuels and cutting forests change these processes and add to climate change.","human impact")],
 ("Explain why a sea breeze blows during the day.",[("Land heats up faster than water.","Uneven heating."),("Warm air over land rises and cooler sea air moves in.","Pressure difference."),("This wind from sea to land is the sea breeze.","Local wind.")]),
 ("How does uneven heating of the Earth drive winds and currents?",["Different heating makes pressure differences","Air moves from high to low pressure","Ocean currents carry heat"],["Thinking the greenhouse effect is entirely harmful"]),
 ["The Sun heats Earth unevenly.","Winds and ocean currents arise from uneven heating.","Matter cycles through water, carbon, nitrogen and oxygen cycles.","Human activity affects these cycles."],
 [mcq("s13-1",1,"Regions near the equator are warmer because","sunlight falls more directly",["they are closer to the Moon","they have more oceans only"],"Direct rays heat more."),
  mcq("s13-2",1,"Greenhouse gases","trap heat in the atmosphere",["remove all heat","stop sunlight"],"They act like a blanket."),
  tf("s13-3",1,"Winds blow from high pressure to low pressure.",True,"That is how pressure differences act."),
  mcq("s13-4",2,"Evaporation, condensation and precipitation form the","water cycle",["carbon cycle","rock cycle"],"Water cycle."),
  mcq("s13-5",2,"Plants take in carbon dioxide during","photosynthesis",["respiration only","evaporation"],"Carbon is fixed."),
  tf("s13-6",2,"Ocean currents move heat around the Earth.",True,"Yes."),
  short("s13-7",3,"Which wind blows from sea to land during the day? (two words)",["sea breeze"],"Sea breeze."),
  mcq("s13-8",3,"Burning fossil fuels mainly adds ___ to the atmosphere.","carbon dioxide",["oxygen","nitrogen only"],"CO2 is released.")])
